A = [int(i) for i in input().split()]
B = [int(i) for i in input().split()]
time = 0
num_A = 0

for i in range(N):
    if time + A[i] > K:
        break
    else:
        time += A[i]
        num_A += 1

ans = num_A

i = 0
while i < M:
    while i < M and time + B[i] <= K:
        time += B[i]
        i += 1
    ans = max(num_A+i, ans)
    if i == M-1:
        break
    elif num_A > 0:
        num_A -= 1
        time -= A[num_A]
    else:
        break

print(ans)

