def binary_search(func, array, left=0, right=-1):
    if right==-1:right=len(array)-1
    while right-left>1:
        middle = (left+right)//2
        if func(array[middle]):
            left = middle
        else:
            right = middle
    if func(array[right]):
        return right
    return left

